state_labels = {
    'draft': 'Draft',
    'in_review': 'In Review',
    'ready_for_pdf': 'Ready for PDF',
    'generated': 'Generated',
    'signature_requested': 'Signature Requested',
    'signed': 'Signed',
    'cancelled': 'Cancelled',
}

checklist_model = env['x_hr.applicant_required_document_checklist'].sudo()

for rec in records.sudo():
    if not rec.x_applicant_id:
        continue

    applicant = rec.x_applicant_id
    applicant_name = applicant.partner_name or applicant.name or applicant.display_name or 'Applicant'

    sequence = checklist_model.search_count([
        ('x_applicant_id', '=', applicant.id),
        ('id', '<', rec.id),
    ]) + 1

    reference = rec.x_document_reference or ('MCEP-HR-F-0003-%05d-%02d' % (applicant.id, sequence))
    state_label = state_labels.get(rec.x_state or 'draft', rec.x_state or 'Draft')

    values = {}
    if rec.x_checklist_sequence != sequence:
        values['x_checklist_sequence'] = sequence
    if not rec.x_document_reference:
        values['x_document_reference'] = reference

    normalized_name = '%s / F-0003 Checklist #%s / %s / %s' % (
        applicant_name,
        sequence,
        reference,
        state_label,
    )
    if rec.x_name != normalized_name:
        values['x_name'] = normalized_name

    if values:
        rec.sudo().write(values)

