checklist_model = env['x_hr.applicant_required_document_checklist'].sudo()
submission_model = env['x_hr.applicant_required_document_submission'].sudo()

state_labels = {
    'draft': 'Draft',
    'in_review': 'In Review',
    'ready_for_pdf': 'Ready for PDF',
    'generated': 'Generated',
    'signature_requested': 'Signature Requested',
    'signed': 'Signed',
    'cancelled': 'Cancelled',
}

for applicant in records.sudo():
    applicant_name = applicant.partner_name or applicant.name or applicant.display_name or 'Applicant'

    checklists = checklist_model.search([
        ('x_applicant_id', '=', applicant.id),
    ], order='id asc')

    for index, checklist in enumerate(checklists, start=1):
        reference = checklist.x_document_reference or ('MCEP-HR-F-0003-%05d-%02d' % (applicant.id, index))
        state_label = state_labels.get(checklist.x_state or 'draft', checklist.x_state or 'Draft')
        normalized_name = '%s / F-0003 Checklist #%s / %s / %s' % (
            applicant_name,
            index,
            reference,
            state_label,
        )

        values = {}
        if checklist.x_checklist_sequence != index:
            values['x_checklist_sequence'] = index
        if not checklist.x_document_reference:
            values['x_document_reference'] = reference
        if checklist.x_name != normalized_name:
            values['x_name'] = normalized_name
        if values:
            checklist.sudo().write(values)

    submissions = submission_model.search([
        ('x_applicant_id', '=', applicant.id),
    ], order='x_checklist_id asc, x_line_id asc, id asc')

    for submission in submissions:
        line = submission.x_line_id
        checklist = submission.x_checklist_id or line.x_checklist_id
        document_type = submission.x_document_type_id or line.x_document_type_id

        values = {}

        if checklist and submission.x_checklist_id != checklist:
            values['x_checklist_id'] = checklist.id
        if document_type and submission.x_document_type_id != document_type:
            values['x_document_type_id'] = document_type.id
        if not submission.x_source:
            values['x_source'] = 'manual'
        if not submission.x_state:
            values['x_state'] = 'submitted'
        if not submission.x_submitted_by_user_id:
            values['x_submitted_by_user_id'] = env.user.id
        if not submission.x_submitted_on:
            values['x_submitted_on'] = datetime.datetime.now()

        if checklist and line:
            sequence = submission_model.search_count([
                ('x_applicant_id', '=', applicant.id),
                ('x_checklist_id', '=', checklist.id),
                ('x_line_id', '=', line.id),
                ('id', '<', submission.id),
            ]) + 1

            if submission.x_submission_sequence != sequence:
                values['x_submission_sequence'] = sequence

            checklist_label = checklist.x_document_reference or checklist.x_name or ('Checklist %s' % checklist.id)

            document_label = False
            if document_type:
                document_label = (
                    document_type.x_name_en
                    or document_type.x_name_ar
                    or document_type.x_name
                    or document_type.display_name
                )
            if not document_label and line:
                document_label = (
                    line.x_document_name_en
                    or line.x_document_name_ar
                    or line.x_name
                    or line.display_name
                )
            if not document_label:
                document_label = 'Required Document'

            normalized_name = '%s / %s / %s / Submission #%s' % (
                applicant_name,
                checklist_label,
                document_label,
                sequence,
            )
            if submission.x_name != normalized_name:
                values['x_name'] = normalized_name

        elif not submission.x_name:
            values['x_name'] = 'Required Document Submission'

        if values:
            submission.sudo().write(values)

    applicant.message_post(
        body='F-0003 checklist and submission identities normalized for clearer selection and review.'
    )

